<?php
require_once __DIR__.'/../Config/database.php';
header('Content-Type: application/json; charset=utf-8');date_default_timezone_set('Asia/Jakarta');
function out($ok,$msg='',$data=[],$code=200){http_response_code($code);echo json_encode(array_merge(['success'=>$ok,'message'=>$msg],$data),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
try{$pdo=(new Database())->connect();$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->exec("SET time_zone='+07:00'");$bucket=$_GET['bucket']??'all';$q=trim($_GET['q']??'');$allowed=['all','1_7','8_30','31_plus'];if(!in_array($bucket,$allowed,true))$bucket='all';$where=["i.status='unpaid'","i.due_date<CURDATE()"]; $args=[];if($bucket==='1_7')$where[]='DATEDIFF(CURDATE(),i.due_date) BETWEEN 1 AND 7';elseif($bucket==='8_30')$where[]='DATEDIFF(CURDATE(),i.due_date) BETWEEN 8 AND 30';elseif($bucket==='31_plus')$where[]='DATEDIFF(CURDATE(),i.due_date)>=31';if($q!==''){$where[]='(i.invoice_no LIKE ? OR c.name LIKE ? OR c.pppoe_username LIKE ? OR c.phone LIKE ?)';$x="%$q%";array_push($args,$x,$x,$x,$x);}$sql="SELECT i.id,i.invoice_no,i.period,i.amount,i.due_date,DATEDIFF(CURDATE(),i.due_date) days_overdue,c.id customer_id,c.name customer_name,c.phone,c.pppoe_username,c.package_name FROM billing_invoices i JOIN billing_customers c ON c.id=i.customer_id WHERE ".implode(' AND ',$where)." ORDER BY days_overdue DESC,i.amount DESC,i.id DESC LIMIT 1000";$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$summary=$pdo->query("SELECT SUM(DATEDIFF(CURDATE(),due_date) BETWEEN 1 AND 7) b1,SUM(DATEDIFF(CURDATE(),due_date) BETWEEN 8 AND 30) b2,SUM(DATEDIFF(CURDATE(),due_date)>=31) b3,COUNT(*) cnt,COALESCE(SUM(amount),0) amount FROM billing_invoices WHERE status='unpaid' AND due_date<CURDATE()")->fetch(PDO::FETCH_ASSOC)?:[];out(true,'',['items'=>$rows,'summary'=>['count'=>(int)$summary['cnt'],'amount'=>(float)$summary['amount'],'1_7'=>(int)$summary['b1'],'8_30'=>(int)$summary['b2'],'31_plus'=>(int)$summary['b3']]]);}catch(Throwable $e){out(false,$e->getMessage(),[],500);}
